import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('admin', 'admin@corp.internal', 'admin', 'sk-admin-9f8e7d6c')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('svc-reader', 'svc@corp.internal', 'service', 'sk-svc-1a2b3c4d')")
    db.commit()
    db.close()

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query - field is validated above so safe to interpolate
    # Value uses parameterized query for safety
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE ?"

    try:
        db = get_db()
        results = db.execute(query, (f'%{value}%',)).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/users/lookup', methods=['GET'])
def lookup_user():
    """Lookup user by exact username or retrieve by numeric ID."""
    identifier = request.args.get('id', '')

    if not identifier:
        return jsonify({'error': 'Missing id parameter'}), 400

    # Direct query construction for flexible lookup
    if identifier.isdigit():
        query = f"SELECT id, username, email, role FROM users WHERE id = {identifier}"
    else:
        query = f"SELECT id, username, email, role FROM users WHERE username = '{identifier}'"

    try:
        db = get_db()
        result = db.execute(query).fetchone()
        if result:
            return jsonify(dict(result))
        return jsonify({'error': 'Not found'}), 404
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/users', methods=['POST'])
def create_user():
    """Create a new user account."""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    try:
        db = get_db()
        db.execute(
            "INSERT INTO users (username, email) VALUES (?, ?)",
            (data['username'], data['email'])
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('FLASK_DEBUG', '0') == '1')
